  47	\section{Games and strategies}
  48	% Paper subsection label sec:strat kept for cross-reference fidelity.
  49	\label{sec:strat}
  50	
  51	\begin{definition}[Two-player one-round games]\label{def:game}
  52		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
  53		\begin{enumerate}
  54			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
  55			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
  56			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
  57			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
  58		\end{enumerate}
  59	\end{definition}
  60	
  61	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
  62		\uses{def:game, def:povm-conventions}
  63		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
  64		\begin{itemize}
  65			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
  66			\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
  67			\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
  68		\end{itemize}
  69	\end{definition}
  70	
  71	\begin{definition}[Tensor product value]\label{def:tensor-product-value}
  72		\uses{def:tensor-product-strategy}
  73		The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
  74		\[
  75			\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
  76		\]
  77		For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
  78		\[
  79			\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
  80		\]
  81		where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
  82	\end{definition}
  83	
  84	Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.
  85	
  86	% The source labels this definition def:projective-strategy. That label is already carried
  87	% by the low individual degree test track (Chapter 2), where it names the strategy format
  88	% specific to that test, so a distinct label is used here; see the following remark.
  89	\begin{definition}[Projective strategies]\label{def:projective-strategy-general}
  90		\lean{MIPStarRE.QPBT.Strategy.IsProjective}
  91		\leanok
  92		\uses{def:tensor-product-strategy, def:povm-conventions}
  93		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{projective} if all the measurements $\{A^x_a\}_a$ and $\{B^y_b\}_b$ are projective.
  94	\end{definition}
  95	
  96	\begin{remark}[Two uses of the term ``projective strategy'']\label{rem:projective-strategy-relation}
  97		Definition~\ref{def:projective-strategy-general} is the general notion: a strategy for an arbitrary nonlocal game all of whose measurements are projective. The low individual degree chapters use the same term for the concrete data of a two-prover strategy for the $(m,q,d)$ low individual degree test (Definition~\ref{def:projective-strategy} in Chapter~\ref{chap:test}); that definition is the specialization of the present notion to the question format of that particular test. The two usages occur in disjoint contexts.
  98	\end{remark}
  99	
 100	\begin{definition}[Symmetric games and symmetric strategies]\label{def:symmetric-game}
 101		\lean{MIPStarRE.QPBT.SymmetricGame, MIPStarRE.QPBT.SymmetricGame.toGame, MIPStarRE.QPBT.SymmetricStrategy, MIPStarRE.QPBT.SymmetricStrategy.toStrategy}
 102		\leanok
 103		% Paper label: rem:symmetric-games (a definition environment carrying a rem: label in the
 104		% source); relabeled here to match the environment kind.
 105		\uses{def:game, def:tensor-product-strategy}
 106		A game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is \emph{symmetric} if the question and answer alphabets are the same for both players (i.e.\ $\mathcal X = \mathcal Y$ and $\mathcal A = \mathcal B$), the distribution $\mu$ is symmetric (i.e.\ $\mu(x,y) = \mu(y,x)$ for all $x,y$), and the decision predicate $D$ treats both players symmetrically (i.e.\ $D(x,y,a,b) = D(y,x,b,a)$ for all $x,y,a,b$).
 107	
 108		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.
 109	\end{definition}
 110	
 111	We often specify symmetric games $\mathfrak G$ and symmetric strategies $\mathcal S$ using a compact notation: we write $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ and $\mathcal S = (\ket{\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.
 112	
 113	% Source statement (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:94-99) kept in
 114	% its original form. The proof below records the approximate form the source argument
 115	% establishes and leaves the final attainment step unproved; see rem:symmetric-strat-limit.
 116	\begin{lemma}[Symmetrization of strategies for symmetric games]\label{lem:symmetric-strat}
 117		\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy}
 118		\leanok
 119		\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
 120		Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game such that $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$. Then there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ such that $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps$.
 121	\end{lemma}
 122	\begin{proof}
 123		\uses{thm:naimark}
 124		The symmetrization argument establishes the following approximate form of the conclusion: for every $\eps' > \eps$ there exists a symmetric and projective strategy of value at least $1-\eps'$. Indeed, fix $\eps' > \eps$. Since $\operatorname{val}^*(\mathfrak G)$ is the supremum of the values of all strategies, there exists a strategy $\mathcal S' = (\ket{\psi'}, A, B)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Using Naimark dilation (Theorem~\ref{thm:naimark}), each dilated sub-measurement being completed to a projective measurement by assigning to one fixed outcome the residual projector of its family --- which changes no correlation on the extended state, as described in Remark~\ref{rem:naimark-for-games} above --- we may assume without loss of generality that $\ket{\psi'} \in \C^d_{A'} \ot \C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let
 125		\[
 126			\ket{\psi} = \frac{1}{\sqrt 2}\, \bigl( \ket{0}_{A}\ket{1}_{B}\ket{\psi'}_{A'B'} + \ket{1}_{A}\ket{0}_{B}\ket{\psi'_\tau}_{A'B'} \bigr) \in \bigl(\C^2_{A} \ot \C^d_{A'}\bigr) \ot \bigl(\C^2_{B} \ot \C^d_{B'}\bigr)\,,
 127		\]
 128		where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi'}$ by permuting the two players' registers; then $\ket{\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \in \mathcal X$ define the projective measurement $M^x = \{M^x_a\}_{a \in \mathcal A}$ on $\C^2 \ot \C^d$ by
 129		\[
 130			M^x_a = \ket{0}\bra{0} \ot A^x_a + \ket{1}\bra{1} \ot B^x_a\,,
 131		\]
 132		and let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\mathcal S = (\ket{\psi}, M)$ satisfies $\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Note that this construction preserves the value of the strategy it is applied to exactly.
 133	
 134		The statement asserts more, namely a single symmetric projective strategy of value at least $1-\eps$ itself. Passing from the family of strategies constructed above to one attaining the bound $1-\eps$ is an attainment step which the argument does not supply: the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} ranges over strategies of unbounded dimension and need not be attained. This step remains unproved; the obstruction, and the forms of the lemma that the argument does prove, are documented in \cite{gap:qpbt_symmetrization-attainment}. See also Remark~\ref{rem:symmetric-strat-limit}.
 135	\end{proof}
 136	
 137	\begin{remark}[Attainment in the symmetrization lemma]\label{rem:symmetric-strat-limit}
 138		The proof of Lemma~\ref{lem:symmetric-strat} yields, for each $\eps' > \eps$, a symmetric projective strategy of value at least $1-\eps'$. The conclusion as stated, at $\eps' = \eps$, does not follow from this: the dilated dimension $d$ may grow as $\eps' \downarrow \eps$, and the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} need not be attained by any strategy. The symmetrization construction itself is value-preserving, so the conclusion does hold whenever the hypothesis supplies an actual strategy of value at least $1-\eps$ rather than only the value of the game; every use of the lemma in the source proceeds from such a strategy, or from a strict lower bound on the value, and therefore consumes only what the proof establishes. The gap and the available repairs are documented in \cite{gap:qpbt_symmetrization-attainment}.
 139	\end{remark}
