 141	\begin{definition}[Commuting strategies]\label{def:comm-strategy}
 142		\lean{MIPStarRE.QPBT.IsCommutingOn, MIPStarRE.QPBT.Strategy.IsCommuting}
 143		\leanok
 144		\uses{def:game, def:tensor-product-strategy}
 145		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a game, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy for $\mathfrak G$ such that $\mathcal H_A = \mathcal H_B$. We say that $\mathcal S$ is a \emph{commuting strategy for $\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\mu$ (i.e.\ all $(x,y)$ with $\mu(x,y) > 0$) we have
 146		\[
 147			[A^x_a, B^y_b] = 0 \qquad \text{for all } a \in \mathcal A,\ b \in \mathcal B\,,
 148		\]
 149		where $[A,B] = AB - BA$ denotes the commutator.
 150	\end{definition}
 151	
 152	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
 153		\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
 154		\leanok
 155		\uses{def:povm-conventions}
 156		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
 157		\[
 158			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
 159		\]
 160		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
 161	\end{definition}
 162	
 163	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
 164	\[
 165		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
 166	\]
 167	where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.
 168	
 169	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
 170		\lean{MIPStarRE.QPBT.IsConsistentStrategyOn, MIPStarRE.QPBT.SymmetricStrategy.IsConsistent}
 171		\leanok
 172		\uses{def:consistent-measurement, def:projective-strategy-general}
 173		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
 174	\end{definition}
 175	
 176	We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.
 177	
 178	\begin{definition}[PCC and SPCC strategies]\label{def:spcc}
 179		\lean{MIPStarRE.QPBT.Strategy.IsPCC, MIPStarRE.QPBT.SymmetricStrategy.IsSPCC}
 180		\leanok
 181		\uses{def:projective-strategy-general, def:consistent-strategy, def:comm-strategy, def:symmetric-game}
 182		We say that a strategy $\mathcal S$ for a game $\mathfrak G$ is \emph{PCC} if it is projective, consistent, and commuting for $\mathfrak G$. Additionally, we say that a PCC strategy $\mathcal S$ is \emph{SPCC} if it is furthermore symmetric.
 183	\end{definition}
