 569	\begin{lemma}[Close strategies have close values; Fact 4.32 in \cite{Natarajan2018NEEXP}]\label{lem:close-strategies-have-close-values}
 570		\lean{MIPStarRE.QPBT.abs_value_sub_le_of_areClose}
 571		\leanok
 572		\uses{def:strategy-distance, def:tensor-product-value, def:projective-strategy-general}
 573		Let $\mathfrak G$ be a nonlocal game, and let $\mathcal S$, $\mathcal S'$ be two strategies that are $\delta$-close in the sense of Definition~\ref{def:strategy-distance}, for some $\delta \in [0,1]$, and that use the same state $\ket{\psi}$. If either $\mathcal S$ or $\mathcal S'$ is projective, then
 574		\[
 575			\bigl| \operatorname{val}^*(\mathfrak G, \mathcal S) - \operatorname{val}^*(\mathfrak G, \mathcal S') \bigr| \le O(\delta^{1/2})\,.
 576		\]
 577	\end{lemma}
 578	\begin{proof}
 579		Stated in the source without proof; it is Fact 4.32 of \cite{Natarajan2018NEEXP}. Write the value difference as an average over $(x,y) \sim \mu$ of sums of terms of the form $\bra{\psi} (A^x_a - (A')^x_a) \ot B^y_b \ket{\psi}$ and $\bra{\psi} (A')^x_a \ot (B^y_b - (B')^y_b) \ket{\psi}$, replacing one player's measurements at a time. The Cauchy--Schwarz inequality bounds each group by the square root of the corresponding averaged squared state-dependent distance, and projectivity of one of the two strategies keeps the accompanying operator sums bounded, giving the total bound $O(\delta^{1/2})$.
 580	\end{proof}
