1146	\section{Typed conditionally linear distributions}
1147	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
1148	% typed material (typed CL functions and distributions, graph distributions) is stated
1149	% here; the typed sampler and verifier machinery of the source is outside the scope of
1150	% the mathematical development.
1151	\label{sec:types}
1152	
1153	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
1154	
1155	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
1156		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
1157		\leanok
1158		\uses{def:cl-func}
1159		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
1160	\end{definition}
1161	
1162	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
1163	% normalization 1/(2m-k) below is undefined. The source
1164	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
1165	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1166		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1167		\[
1168			\mu_G(u, v) =
1169			\begin{cases}
1170				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1171				0 & \text{otherwise}\,.
1172			\end{cases}
1173		\]
1174		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1175	\end{definition}
1176	
1177	% The nonempty-edge hypothesis on G is inherited from def:graph-distribution, where it is
1178	% needed for the graph distribution mu_G to be defined; the source
1179	% (references/qpbt-paper/07_types.tex:84-93) leaves it implicit here as well.
1180	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
1181		\lean{MIPStarRE.QPBT.typedCLDistribution, MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL, MIPStarRE.QPBT.pauliQuestionDistribution_eq_typedCL}
1182		\leanok
1183		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
1184		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$ and nonempty edge set $E$, so that the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} is defined. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
1185	\end{definition}

  1	\chapter{Games, strategies, and conditionally linear distributions}
  2	\label{chap:qpbt-games}
  3	% Paper label sec:games kept for cross-reference fidelity; resolves to the chapter number.
  4	\label{sec:games}
  5	
  6	This chapter records the vocabulary in which the quantum Pauli basis test and its analysis are phrased: two-player one-round games and tensor product strategies, the consistency and state-dependent distance calculus for families of measurements, and conditionally linear functions and distributions, the class of question distributions used by the tests of Chapter~\ref{chap:qpbt-test}. The presentation follows \cite{Ji2020MIPStar}; the distance calculus is imported there from \cite{Natarajan2018NEEXP} and \cite{Ji2020LowIndividualDegree}.
  7	
  8	\section{Measurements and observables}
  9	
 10	\begin{definition}[POVMs, sub-measurements, and observables]\label{def:povm-conventions}
 11		\uses{def:submeasurement}
 12		% Finiteness of the outcome set is stated explicitly here; the source leaves it implicit,
 13		% and the measurement and submeasurement definitions referenced below assume finite
 14		% outcome sets.
 15		Quantum measurements are modeled as positive operator-valued measures (POVMs). A \emph{POVM} on a finite-dimensional Hilbert space $\mathcal H$ is a family of positive semidefinite operators $\{M_a\}_{a \in S}$ indexed by outcomes $a$ ranging over a finite set $S$ such that $\sum_a M_a = \Id$; if the latter condition is relaxed to $\sum_a M_a \le \Id$, then $\{M_a\}$ is a \emph{sub-measurement}. (POVMs and sub-measurements are thus exactly the measurements and submeasurements of Definition~\ref{def:submeasurement}.) The probability that the measurement returns outcome $a$ on a state $\ket{\psi}$ is
 16		\[
 17			\Prb(a) = \bra{\psi} M_a \ket{\psi}\,.
 18		\]
 19		A POVM $M = \{M_a\}$ is \emph{projective} if each operator $M_a$ is a projector ($M_a^2 = M_a$); this automatically implies that $M_a M_b = M_b M_a = 0$ for distinct outcomes $a \ne b$. An \emph{observable} is a unitary matrix. A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$ has eigenvalues in $\{-1,1\}$.
 20	
 21		Subscripts of a measurement index the outcome, and superscripts index different measurements. When the outcome of a measurement $\{M^x_{a,\,b}\}$ consists of two parts $a$ and $b$, we write $\{M^x_a\}$ and $\{M^x_b\}$ for its \emph{marginals}
 22		\[
 23			M^x_a = \sum_b M^x_{a,\,b}\,, \qquad M^x_b = \sum_a M^x_{a,\,b}\,;
 24		\]
 25		for every $x$ both marginals are again POVMs.
 26	\end{definition}
 27	
 28	\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
 29		\lean{MIPStarRE.Quantum.Measurement.postprocess}
 30		\leanok
 31		\uses{def:povm-conventions, def:post-processing}
 32		Let $\mathcal A$ and $\mathcal B$ be finite sets, let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
 33		\[
 34			M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
 35		\]
 36		and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
 37		\[
 38			M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
 39		\]
 40		For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
 41	\end{definition}
